local CrystallizationDishMaker = {}
local PRODUCTS = {
    simple_clay_crystallization = { name = "Preprosta glinena kristalizacijska posoda", clayCost = 3, glassCost = 1, time = 4, cost = 70, science = 18, happiness = 1, description = "Preprosta glinena kristalizacijska posoda za kristalizacijo." },
    glass_crystallization_dish = { name = "Steklena kristalizacijska posoda", glassCost = 3, clayCost = 2, time = 6, cost = 180, science = 32, happiness = 1, prestige = 2, description = "Steklena kristalizacijska posoda za trgovce." },
    silver_rim_crystallization = { name = "Srebrnorobna kristalizacijska posoda", glassCost = 3, silverCost = 1, clayCost = 2, time = 10, cost = 440, science = 48, happiness = 2, prestige = 6, description = "Srebrnorobna kristalizacijska posoda za plemiče." },
    gold_trimmed_crystallization = { name = "Zlatookrasna kristalizacijska posoda", glassCost = 4, goldCost = 1, silverCost = 1, clayCost = 2, time = 14, cost = 1100, science = 62, happiness = 3, prestige = 14, description = "Zlatookrasna kristalizacijska posoda za visoke plemiče." },
    jewel_set_crystallization = { name = "Draguljasta kristalizacijska posoda", glassCost = 4, goldCost = 1, silverCost = 1, clayCost = 2, jewelCost = 1, time = 18, cost = 2400, science = 78, happiness = 5, prestige = 27, description = "Kristalizacijska posoda z draguljem za visoko plemstvo." },
    royal_grand_crystallization = { name = "Kraljevski veliki kristalizacijska posoda", glassCost = 6, goldCost = 2, silverCost = 2, clayCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 5200, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska kristalizacijska posoda z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    crystallization_workshop = { name = "Kristalizacijska delavnica", cost = { gold = 270, wood = 120, stone = 140, clay = 8, glass = 6 }, upkeep = 6, qualityBonus = 5 },
    alchemy_loft = { name = "Alkemična podstrešje", cost = { gold = 980, wood = 280, stone = 280, silver = 6, brass = 6 }, upkeep = 22, qualityBonus = 18 },
    master_crystallization_atelier = { name = "Mojstrski kristalizacijski atelje", cost = { gold = 2650, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 61, qualityBonus = 30 },
    royal_alchemy_palace = { name = "Kraljevska alkemična palača", cost = { gold = 11300, wood = 580, stone = 760, gold = 72, jewel = 18 }, upkeep = 225, qualityBonus = 55, prestigeBonus = 50 },
}
CrystallizationDishMaker.clayStock = 14; CrystallizationDishMaker.glassStock = 14; CrystallizationDishMaker.silverStock = 6; CrystallizationDishMaker.goldStock = 6; CrystallizationDishMaker.jewelStock = 4; CrystallizationDishMaker.pearlStock = 4
CrystallizationDishMaker.productStock = {}; CrystallizationDishMaker.buildings = {}; CrystallizationDishMaker.maker = nil; CrystallizationDishMaker.activeMaking = {}; CrystallizationDishMaker.totalProducts = 0; CrystallizationDishMaker.dayTimer = 0
function CrystallizationDishMaker.init() CrystallizationDishMaker.clayStock=14; CrystallizationDishMaker.glassStock=14; CrystallizationDishMaker.silverStock=6; CrystallizationDishMaker.goldStock=6; CrystallizationDishMaker.jewelStock=4; CrystallizationDishMaker.pearlStock=4; CrystallizationDishMaker.productStock={}; CrystallizationDishMaker.buildings={}; CrystallizationDishMaker.maker=nil; CrystallizationDishMaker.activeMaking={}; CrystallizationDishMaker.totalProducts=0; CrystallizationDishMaker.dayTimer=0; print("[CrystallizationDishMaker] Royal Crystallization Dish Maker System initialized (6 products, 4 buildings)") end
function CrystallizationDishMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrystallizationDishMaker.maker={name=n or ("Kristalizar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kristalizar najet: %s (spretnost: %d)",CrystallizationDishMaker.maker.name,s),"success") end; return true end
function CrystallizationDishMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrystallizationDishMaker.build(id) local ok,e=CrystallizationDishMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrystallizationDishMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrystallizationDishMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrystallizationDishMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrystallizationDishMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and CrystallizationDishMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and CrystallizationDishMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and CrystallizationDishMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrystallizationDishMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrystallizationDishMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrystallizationDishMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrystallizationDishMaker.buildings==0 then return false,"Potrebna kristalizacijska delavnica" end; if not CrystallizationDishMaker.maker then return false,"Potreben kristalizar" end; return true end
function CrystallizationDishMaker.make(pt,qty) qty=qty or 1; local ok,e=CrystallizationDishMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then CrystallizationDishMaker.clayStock=CrystallizationDishMaker.clayStock-d.clayCost*qty end; if d.glassCost then CrystallizationDishMaker.glassStock=CrystallizationDishMaker.glassStock-d.glassCost*qty end; if d.silverCost then CrystallizationDishMaker.silverStock=CrystallizationDishMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrystallizationDishMaker.goldStock=CrystallizationDishMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrystallizationDishMaker.jewelStock=CrystallizationDishMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrystallizationDishMaker.pearlStock=CrystallizationDishMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrystallizationDishMaker.maker then t=math.max(1,t-math.floor(CrystallizationDishMaker.maker.skill/13)) end; table.insert(CrystallizationDishMaker.activeMaking,{id="crystallizationdish_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrystallizationDishMaker.completeMaking(m) local q=1.0+(CrystallizationDishMaker.getQualityBonus()/100); if CrystallizationDishMaker.maker then q=q+(CrystallizationDishMaker.maker.skill/140) end; q=math.min(2.5,q); CrystallizationDishMaker.productStock[m.productType]=(CrystallizationDishMaker.productStock[m.productType] or 0)+m.quantity; CrystallizationDishMaker.totalProducts=CrystallizationDishMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrystallizationDishMaker.maker then CrystallizationDishMaker.maker.itemsMade=CrystallizationDishMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrystallizationDishMaker.maker.skill=math.min(100,CrystallizationDishMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kristalizacijska posoda izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crystallizationdish.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function CrystallizationDishMaker.update(dt) if not _G.state then return end; CrystallizationDishMaker.dayTimer=CrystallizationDishMaker.dayTimer+dt; if CrystallizationDishMaker.dayTimer>=30 then CrystallizationDishMaker.dayTimer=0; for i=#CrystallizationDishMaker.activeMaking,1,-1 do local m=CrystallizationDishMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrystallizationDishMaker.completeMaking(m); table.remove(CrystallizationDishMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrystallizationDishMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrystallizationDishMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrystallizationDishMaker.getStats() return {clayStock=CrystallizationDishMaker.clayStock,glassStock=CrystallizationDishMaker.glassStock,silverStock=CrystallizationDishMaker.silverStock,goldStock=CrystallizationDishMaker.goldStock,jewelStock=CrystallizationDishMaker.jewelStock,pearlStock=CrystallizationDishMaker.pearlStock,productStock=CrystallizationDishMaker.productStock,numBuildings=#CrystallizationDishMaker.buildings,hasMaker=CrystallizationDishMaker.maker~=nil,makerName=CrystallizationDishMaker.maker and CrystallizationDishMaker.maker.name or "—",makerSkill=CrystallizationDishMaker.maker and CrystallizationDishMaker.maker.skill or 0,activeMaking=#CrystallizationDishMaker.activeMaking,totalProducts=CrystallizationDishMaker.totalProducts} end
return CrystallizationDishMaker
